	@Test
	void conflictingReplayAndInterruptedInputLeaveTheWholeBatchUncommitted(@TempDir Path directory) throws Exception {
		Fixture first = fixture(BASELINE + 1, EMPTY, "first");
		Fixture second = fixture(BASELINE + 2, first.stage.id, "second");
		Fixture third = fixture(BASELINE + 3, second.stage.id, "third");
		try (LmdbBackupJournal journal = writable(directory)) {
			journal.append(List.of(first.stage), stage -> first.open());
			byte[] conflicting = first.bytes.clone();
			conflicting[conflicting.length - 1] ^= 1;
			assertThrows(IOException.class, () -> journal.append(List.of(first.stage, second.stage),
					stage -> stage.transaction == first.stage.transaction ? new ByteArrayInputStream(conflicting)
							: second.open()));
			assertThrows(IOException.class, () -> journal.append(List.of(second.stage, third.stage), stage -> {
				if (stage.transaction == third.stage.transaction) {
					throw new IOException("Source interrupted before the second stage");
				}
				return second.open();
			}));
			assertEquals(BASELINE + 1, journal.headTransaction());
			assertEquals(List.of(BASELINE + 1), journal.transactions(BASELINE, Long.MAX_VALUE));
		}
	}

