	@Test
	void readOnlyArchiveAdoptsMapGrowthFromAnotherProcess(@TempDir Path directory) throws Exception {
		Path archive = directory.resolve("journal");
		Fixture first = fixture(BASELINE + 1, EMPTY, "before-external-growth");
		try (LmdbBackupJournal writer = new LmdbBackupJournal(archive, GENERATION, true, BASELINE, EMPTY,
				64L << 10)) {
			writer.append(List.of(first.stage), stage -> first.open());
		}
		try (LmdbBackupJournal reader = new LmdbBackupJournal(archive, GENERATION, false, 0, EMPTY)) {
			assertEquals(List.of(first.stage.transaction), reader.transactions(BASELINE, Long.MAX_VALUE));
			Path output = directory.resolve("journal-resize-child.log");
			Process child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
					"-Xmx256m", "-XX:ActiveProcessorCount=2", "-ea", "-cp",
					System.getProperty("surefire.test.class.path", System.getProperty("java.class.path")),
					LmdbBackupJournalTest.class.getName(), "grow", archive.toString())
							.redirectErrorStream(true)
							.redirectOutput(output.toFile())
							.start();
			boolean interrupted = false;
			try {
				assertTrue(child.waitFor(30, TimeUnit.SECONDS), () -> "Archive resize child did not finish: " + output);
				assertEquals(0, child.exitValue(), Files.readString(output));
			} catch (InterruptedException failure) {
				interrupted = true;
				throw failure;
			} finally {
				try {
					if (child.isAlive()) {
						child.destroyForcibly();
						long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
						while (child.isAlive() && System.nanoTime() < deadline) {
							try {
								child.waitFor(Math.max(1, deadline - System.nanoTime()), TimeUnit.NANOSECONDS);
							} catch (InterruptedException failure) {
								interrupted = true;
							}
						}
						assertTrue(!child.isAlive(), "Archive resize child must terminate during cleanup");
					}
				} finally {
					if (interrupted) {
						Thread.currentThread().interrupt();
					}
				}
			}
			assertTrue(Files.size(archive.resolve("data.mdb")) > (16L << 20),
					"The child must exceed the readonly handle's original map with actual committed pages");
			List<Long> transactions = assertDoesNotThrow(() -> reader.transactions(BASELINE, Long.MAX_VALUE),
					"A live archive reader must adopt a map grown by another process");
			assertEquals(LongStream.rangeClosed(BASELINE + 1, BASELINE + 129).boxed().toList(), transactions);
			Fixture last = fixture(BASELINE + 129, new UUID(0x12345678, BASELINE + 128), resizeLabel());
			assertArrayEquals(first.bytes, reader.openStage(first.stage.transaction).readAllBytes());
			assertArrayEquals(last.bytes, reader.openStage(last.stage.transaction).readAllBytes());
		}
	}

