	private static Fixture fixture(long transaction, UUID predecessor, String label) throws IOException {
		var factory = SimpleValueFactory.getInstance();
		List<Record> records = List.of(new Record(true, true, factory.createStatement(factory.createIRI("urn:subject"),
				factory.createIRI("urn:predicate"), factory.createLiteral(label))));
		Stage stage = new Stage(new UUID(0x12345678, transaction), predecessor, transaction, transaction - 1,
				records.size(), null);
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(bytes)) {
			output.writeInt(PostCommitBackupPublisher.MAGIC);
			output.writeLong(stage.id.getMostSignificantBits());
			output.writeLong(stage.id.getLeastSignificantBits());
			output.writeLong(predecessor.getMostSignificantBits());
			output.writeLong(predecessor.getLeastSignificantBits());
			output.writeLong(transaction);
			output.writeLong(transaction - 1);
			output.writeInt(records.size());
			for (Record record : records) {
				LmdbBackupDeltaCodec.writeRecord(output, record);
			}
		}
		return new Fixture(stage, bytes.toByteArray(), records);
	}

	private static void replaceWithLegacyRawChunks(Path directory, Fixture fixture) throws IOException {
		long environment = 0;
		ByteBuffer contents = MemoryUtil.memAlloc(65_536);
		try (MemoryStack stack = MemoryStack.stackPush()) {
			var handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
			E(mdb_env_set_mapsize(environment, 8L << 20));
			E(mdb_env_open(environment, directory.toString(), MDB_NOTLS, 0644));
			LmdbUtil.writeTransaction(environment, (frame, transaction) -> {
				var database = frame.mallocInt(1);
				E(mdb_dbi_open(transaction, (ByteBuffer) null, 0, database));
				ByteBuffer keyBytes = frame.malloc(13).order(ByteOrder.BIG_ENDIAN);
				MDBVal key = MDBVal.malloc(frame);
				MDBVal value = MDBVal.malloc(frame);
				for (int offset = 0, chunk = 0; offset < fixture.bytes.length; chunk++) {
					int length = Math.min(contents.capacity(), fixture.bytes.length - offset);
					keyBytes.clear().put((byte) 1).putLong(fixture.stage.transaction).putInt(chunk).flip();
					contents.clear().put(fixture.bytes, offset, length).flip();
					E(mdb_put(transaction, database.get(0), key.mv_data(keyBytes), value.mv_data(contents), 0));
					offset += length;
				}
				return null;
			});
		} finally {
			if (environment != 0) {
				mdb_env_close(environment);
			}
			MemoryUtil.memFree(contents);
		}
	}
